package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen1Test {

    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a dummy header of a specific size.
     */
    private byte[] createHeader(int size) {
        return new byte[size];
    }

    @Test
    public void testVerifyCheckSum_EmptyHeader() {
        byte[] header = new byte[0];
        // storedSum=0, unsignedSum=0, signedSum=0 -> true
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_ValidUnsignedMatch() {
        // We need to satisfy: storedSum == unsignedSum
        // Since the checksum field is replaced by ' ', unsignedSum adds 32 (' ') for each checksum byte.
        // Let's build a small header where the checksum field is outside the range or we manually calculate.
        // However, the loop processes the whole array.

        // Let's target a simple case: header length < CHKSUM_OFFSET
        // If length is 5, and all bytes are 1.
        // unsignedSum = 1+1+1+1+1 = 5. storedSum = 0. Fail.

        // To get a match, let's use a header where the checksum field is NOT reached,
        // and the sum of bytes equals 0.
        byte[] header = new byte[10];
        Arrays.fill(header, (byte) 0);
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_ValidSignedMatch() {
        // signedSum can be negative.
        // Let's create a header where sum is 0.
        byte[] header = new byte[2];
        header[0] = (byte) 1;
        header[1] = (byte) -1;
        // storedSum = 0. signedSum = 0. unsignedSum = 1 + 255 = 256.
        // 0 == 0 || 0 == 256 -> true
        assertTrue(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_ChecksumFieldLogic_ValidOctal() {
        // header size must be at least CHKSUM_OFFSET + CHKSUMLEN
        int size = CHKSUM_OFFSET + CHKSUMLEN + 1;
        byte[] header = new byte[size];

        // 1. Fill header with 0s. 
        // unsignedSum (initially) = 0.
        // 2. Set checksum field to '0000000' (7 digits, but code takes 6)
        // The loop: if ('0' <= b && b <= '7' && digits++ < 6) { storedSum = storedSum * 8 + b - '0'; }
        // If we put '0000000' at offset 148:
        // storedSum will be 0.
        // The checksum bytes are replaced by ' ' (32).
        // unsignedSum = sum(original bytes except checksum) + (8 * 32).
        // This is tricky to balance. Let's work backwards.

        // Let's try to make storedSum = unsignedSum
        // Let header be all 0 except at checksum offset.
        // Let's say header[0] = 32 * 8 = 256. But byte is signed.
        // Let's use a simpler approach:
        // If we make the checksum field consist of non-octal characters, digits becomes 6.

        // Test the "else if (digits > 0) { digits = 6; }" branch
        byte[] header2 = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        header2[CHKSUM_OFFSET] = '8'; // Not 0-7
        // digits is 0, so it goes to the else if (digits > 0) which is false.
        // Then b becomes ' '.
        // unsignedSum = 32 * 8 = 256. storedSum = 0.
        assertFalse(TarUtils.verifyCheckSum(header2));
    }

    @Test
    public void testVerifyCheckSum_FullOctalDigits() {
        // Test the digits < 6 and digits = 6 logic
        byte[] header = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        // Set checksum to '0000001'
        // digits will increment 6 times.
        // storedSum = 1.
        // checksum bytes (8 bytes) become ' ' (32).
        // unsignedSum = 8 * 32 = 256.
        // signedSum = 8 * 32 = 256.
        // 1 == 256 is false.

        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET+1] = '0';
        header[CHKSUM_OFFSET+2] = '0';
        header[CHKSUM_OFFSET+3] = '0';
        header[CHKSUM_OFFSET+4] = '0';
        header[CHKSUM_OFFSET+5] = '0';
        header[CHKSUM_OFFSET+6] = '1';
        header[CHKSUM_OFFSET+7] = '2'; // 7th digit, triggers else if (digits > 0) digits = 6

        // storedSum calculation:
        // i=148: b='0', storedSum = 0, digits=1
        // i=149: b='0', storedSum = 0, digits=2
        // i=150: b='0', storedSum = 0, digits=3
        // i=151: b='0', storedSum = 0, digits=4
        // i=152: b='0', storedSum = 0, digits=5
        // i=153: b='0', storedSum = 0, digits=6
        // i=154: b='1', digits is 6 (not < 6), goes to else if (digits > 0) digits = 6
        // i=155: b='2', digits is 6, goes to else if (digits > 0) digits = 6

        // To make it true, we need storedSum == unsignedSum.
        // Let's force storedSum = 256.
        // 256 in octal is 400.
        // 400 = 4 * 8^2 + 0 * 8^1 + 0 * 8^0.
        // We need 6 digits to satisfy digits < 6.
        // Let's try digits = 000400.
        // storedSum = 4 * 8^2 = 256.
        // Checksum bytes (8 bytes) become ' ' (32).
        // unsignedSum = 8 * 32 = 256.
        // Perfect.

        byte[] headerMatch = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        headerMatch[CHKSUM_OFFSET] = '0';
        headerMatch[CHKSUM_OFFSET+1] = '0';
        headerMatch[CHKSUM_OFFSET+2] = '0';
        headerMatch[CHKSUM_OFFSET+3] = '4';
        headerMatch[CHKSUM_OFFSET+4] = '0';
        headerMatch[CHKSUM_OFFSET+5] = '0';
        headerMatch[CHKSUM_OFFSET+6] = '0'; // digits becomes 7
        headerMatch[CHKSUM_OFFSET+7] = '0';

        // Calculation:
        // i=148: b='0', storedSum=0, digits=1
        // i=149: b='0', storedSum=0, digits=2
        // i=150: b='0', storedSum=0, digits=3
        // i=151: b='4', storedSum=4, digits=4
        // i=152: b='0', storedSum=4*8=32, digits=5
        // i=153: b='0', storedSum=32*8=256, digits=6
        // i=154: b='0', digits=6 (not < 6), digits=6
        // i=155: b='0', digits=6 (not < 6), digits=6
        // unsignedSum = 8 * 32 = 256.
        // 256 == 256 -> true.
        assertTrue(TarUtils.verifyCheckSum(headerMatch));
    }

    @Test
    public void testVerifyCheckSum_NonOctalInChecksum() {
        byte[] header = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        header[CHKSUM_OFFSET] = '9'; // Not 0-7
        // digits = 0.
        // else if (digits > 0) is skipped.
        // b becomes ' '.
        // unsignedSum = 8 * 32 = 256.
        // storedSum = 0.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_DigitsExceedSix() {
        byte[] header = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        // Fill with '1's. 
        // First 6 '1's will make storedSum = 111111 (octal) = 37457
        // The 7th '1' will trigger digits = 6.
        for (int i = 0; i < CHKSUMLEN; i++) {
            header[CHKSUM_OFFSET + i] = '1';
        }
        // storedSum = 1*8^5 + 1*8^4 + 1*8^3 + 1*8^2 + 1*8^1 + 1*8^0 = 37457
        // unsignedSum = 8 * 32 = 256.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_SignedSumMatch() {
        // We need storedSum == signedSum
        // If we use values that make signedSum equal to storedSum.
        // Let's use the 256 match but ensure signedSum is also 256.
        // Since ' ' is 32, 8 * 32 is 256 (positive).
        // So if unsignedSum is 256, signedSum is 256.
        byte[] headerMatch = new byte[CHKSUM_OFFSET + CHKSUMLEN];
        headerMatch[CHKSUM_OFFSET] = '0';
        headerMatch[CHKSUM_OFFSET+1] = '0';
        headerMatch[CHKSUM_OFFSET+2] = '0';
        headerMatch[CHKSUM_OFFSET+3] = '4';
        headerMatch[CHKSUM_OFFSET+4] = '0';
        headerMatch[CHKSUM_OFFSET+5] = '0';
        headerMatch[CHKSUM_OFFSET+6] = '0';
        headerMatch[CHKSUM_OFFSET+7] = '0';
        assertTrue(TarUtils.verifyCheckSum(headerMatch));
    }
}
